  private _setFromGfCamera(camera: GfCameraValue, time: number | undefined): void {
    const set = (attr: Attribute, value: unknown): void => {
      if (time === undefined) attr.set(value)
      else attr.setTimeSample(time, value)
    }
    const parentToWorldInverse = new GfMatrix4d(
      ...new XformCache(time).getParentToWorldTransform(this._prim)).getInverse()
    const camMatrix = camera.getTransform().getMultiply(parentToWorldInverse)

    const xformOp = this.makeMatrixXform()
    // The returned xformOp may be invalid if there are xform op opinions in
    // the composed layer stack stronger than that of the current edit target.
    if (!xformOp.isDefined()) return
    set(xformOp.getAttr(), camMatrix)

    set(this._declareAttr('projection', 'token'),
      camera.GetProjection() === GfCameraValue.Orthographic ? 'orthographic' : 'perspective')
    set(this._declareAttr('horizontalAperture', 'float'), camera.GetHorizontalAperture())
    set(this._declareAttr('verticalAperture', 'float'), camera.getVerticalAperture())
    set(this._declareAttr('horizontalApertureOffset', 'float'), camera.getHorizontalApertureOffset())
    set(this._declareAttr('verticalApertureOffset', 'float'), camera.getVerticalApertureOffset())
    set(this._declareAttr('focalLength', 'float'), camera.getFocalLength())
    const range = camera.getClippingRange()
    set(this._declareAttr('clippingRange', 'float2'), [range.getMin(), range.getMax()])
    set(this._declareAttr('clippingPlanes', 'float4[]'),
      camera.getClippingPlanes().map(plane => [...plane.data]))
    set(this._declareAttr('fStop', 'float'), camera.getFStop())
    set(this._declareAttr('focusDistance', 'float'), camera.getFocusDistance())
  }

