  computeLinearExposureScale(time?: number): number {
    const prim = this._prim
    const exposure = asNumber(attrVal(prim, 'exposure', time), 0)
    const exposureTime = asNumber(attrVal(prim, 'exposure:time', time), 1)
    const iso = asNumber(attrVal(prim, 'exposure:iso', time), 100)
    const fStop = asNumber(attrVal(prim, 'exposure:fStop', time), 1)
    const responsivity = asNumber(attrVal(prim, 'exposure:responsivity', time), 1)
    return responsivity * exposureTime * (iso / 100) * Math.pow(2, exposure) / (fStop * fStop)
  }

