// UsdGeomCamera — transformable camera.
// Reference: pxr/usd/usdGeom/camera.h, schema.usda fallbacks.
//
// Apertures and focal length are in tenths of scene units (GfCamera
// convention: APERTURE_UNIT = 0.1, FOCAL_LENGTH_UNIT = 0.1) — for the
// common cm-scene case that means millimeters.



import { XformCache } from './xformCache.ts'
import type { Matrix4 } from 'typescript-usd/gf'
import { GfCamera as GfCameraValue, GfMatrix4d, GfRange1f } from 'typescript-usd/gf/camera'
import { attrVal, asNumber, asToken, plain } from './valueUtils.ts'

export type Projection = 'perspective' | 'orthographic'
export type StereoRole = 'mono' | 'left' | 'right'

// GfCamera-equivalent value object: the camera state at one time. The frustum
// math itself lives in typescript-usd/gf (GfCamera/GfFrustum) — this record is only the
// JS-idiomatic carrier for the schema attributes UsdGeomCamera::GetCamera reads.
export interface GfCamera {
  projection: Projection
  horizontalAperture: number
  verticalAperture: number
  horizontalApertureOffset: number
  verticalApertureOffset: number
  focalLength: number
  clippingRange: [number, number]
  fStop: number
  focusDistance: number
}

export const CAMERA_DEFAULTS: GfCamera = {
  projection: 'perspective',
  horizontalAperture: GfCameraValue.DEFAULT_HORIZONTAL_APERTURE,
  verticalAperture: GfCameraValue.DEFAULT_VERTICAL_APERTURE,
  horizontalApertureOffset: 0,
  verticalApertureOffset: 0,
  focalLength: 50,
  clippingRange: [1, 1000000],
  fStop: 0,
  focusDistance: 0,
}

function float2(prim: Prim, name: string, fallback: [number, number], time?: number): [number, number] {
  const v = plain(attrVal(prim, name, time))
  if (Array.isArray(v) && v.length >= 2) return [Number(v[0]), Number(v[1])]
  return fallback
}


// Clip-space transform remapping GL depth [-1,1] to WGSL depth [0,1]:
// z' = 0.5·z + 0.5·w. Row-vector convention, so it post-multiplies the
// projection matrix.
const GL_TO_WGSL_DEPTH = new GfMatrix4d().setIdentity()
GL_TO_WGSL_DEPTH.SetElement(2, 2, 0.5)
GL_TO_WGSL_DEPTH.SetElement(3, 2, 0.5)

// Projection matrix for a GfCamera. Row-major, row-vector convention
// (matches the rest of typescript-usd); camera looks down −Z.
//
// The frustum math is GfCamera::GetFrustum() + GfFrustum::
// ComputeProjectionMatrix() (typescript-usd/gf camera.ts/frustum.ts), with ONE
// deliberate platform re-expression applied on top: the depth (z) component
// is remapped from OpenGL's [-1,1] to [0,1]. This is idiomatic, not
// divergent — typescript-usd renders through WebGPU, whose WGSL clip space requires
// z ∈ [0,1], and every renderer here authors its own projection in this same
// [0,1] form (see typescript-usd/hd camera.ts GetViewProjection and the viewer's
// camera.ts perspective()). Emitting GL [-1,1] here would be inconsistent
// with the matrices the renderers actually use. The x/y/offset structure
// (the part that positions the frustum window) comes straight from GfFrustum.
export function computeProjectionMatrix(camera: GfCamera): Matrix4 {
  const [near, far] = camera.clippingRange
  const gfCamera = new GfCameraValue(
    undefined,
    camera.projection === 'orthographic'
      ? GfCameraValue.Orthographic
      : GfCameraValue.Perspective,
    camera.horizontalAperture,
    camera.verticalAperture,
    camera.horizontalApertureOffset,
    camera.verticalApertureOffset,
    camera.focalLength,
    new GfRange1f(near, far),
  )
  const projection = gfCamera
    .getFrustum()
    .computeProjectionMatrix()
    .getMultiply(GL_TO_WGSL_DEPTH)
  return [...projection.GetArray()] as unknown as Matrix4
}
